    static func tipLines(event: StreamEvent?, scenario: Scenario, large: Bool) -> [String] {
        if let event { return eventTips[event.rawValue] ?? [] }
        let lines = (sceneTips[scenario.rawValue] ?? []) + generalTips
        return large ? lines.filter { !$0.lowercased().contains("little") && !$0.lowercased().contains("small") } : lines
    }
