struct TextMemory {
    private var exact: Set<String> = []
    private var recent: [Set<String>] = []
    static func canonical(_ text: String) -> String {
        let words = text.lowercased().replacingOccurrences(of: "’", with: "'").split { !$0.isLetter && !$0.isNumber }.map(String.init)
        return words.joined(separator: " ")
    }
    static func valid(_ text: String, maxLength: Int = 170) -> Bool {
        let value = text.trimmingCharacters(in: .whitespacesAndNewlines)
        let lower = value.lowercased()
        guard value.count >= 2, value.count <= maxLength, !value.contains("\n"), !value.contains("\r"), !lower.contains("http"), !value.contains("<"), !value.contains(">") else { return false }
        return !["as an ai", "language model", "simulation", "simulated", "system prompt", "ignore previous", "credit card", "payment confirmed"].contains(where: lower.contains)
    }
    private static func tokens(_ text: String) -> Set<String> {
        let stop: Set<String> = ["i", "a", "the", "it", "is", "and", "to", "for", "of", "that", "this", "in", "on", "my", "you", "your", "we", "me", "s", "t", "m", "ve", "re", "just", "really", "so", "but", "with", "some"]
        return Set(canonical(text).split(separator: " ").map(String.init)).subtracting(stop)
    }
    func allows(_ text: String) -> Bool {
        guard Self.valid(text), !exact.contains(Self.canonical(text)) else { return false }
        let tokens = Self.tokens(text)
        guard tokens.count >= 3 else { return true }
        return !recent.contains { previous in
            guard previous.count >= 3 else { return false }
            let overlap = Double(tokens.intersection(previous).count)
            return overlap / Double(tokens.union(previous).count) >= 0.64 || (min(tokens.count, previous.count) >= 4 && overlap / Double(min(tokens.count, previous.count)) >= 0.86)
        }
    }
    @discardableResult mutating func accept(_ text: String) -> Bool {
        guard allows(text) else { return false }
        exact.insert(Self.canonical(text)); recent.append(Self.tokens(text))
        if recent.count > 160 { recent.removeFirst(recent.count - 160) }
        return true
    }
}
